def get_secrets(self, from_date_added=0):
	secrets = []
	for row in self.cursor.execute('SELECT encrypted, json_id, date_added FROM secret WHERE date_added > ? ORDER BY date_added DESC', (from_date_added,)):
		aes_key, json_id, date_added = cryptlib.eciesDecrypt(row[0], self.privkey), row[1], row[2]
		if aes_key != None:
			secrets.append([aes_key, json_id])
		from_date_added = max(from_date_added, date_added)
	return (secrets, from_date_added)

def _ensure_vdisk_no_fc_mappings(self, name, allow_snaps=True):

    mapping_ids = self._get_vdisk_fc_mappings(name)
    while len(mapping_ids):
        wait_for_copy = False
        for map_id in mapping_ids:
            attrs = self._get_flashcopy_mapping_attributes(map_id)
            if not attrs:
                continue
            source = attrs['source_vdisk_name']
            target = attrs['target_vdisk_name']
            copy_rate = attrs['copy_rate']
            status = attrs['status']

            if copy_rate == '0':

                if source == name:
                    if not allow_snaps:
                        return False
                    ssh_cmd = ['svctask', 'chfcmap', '-copyrate', '50',
                               '-autodelete', 'on', map_id]
                    out, err = self._run_ssh(ssh_cmd)
                    wait_for_copy = True

                else:
                    msg = (_('Vdisk %(name)s not involved in '
                             'mapping %(src)s -> %(tgt)s') %
                           {'name': name, 'src': source, 'tgt': target})
                    self._driver_assert(target == name, msg)
                    if status in ['copying', 'prepared']:
                        self._run_ssh(['svctask', 'stopfcmap', map_id])
                    elif status in ['stopping', 'preparing']:
                        wait_for_copy = True
                    else:
                        self._run_ssh(['svctask', 'rmfcmap', '-force',
                                       map_id])

            else:
                if status == 'prepared':
                    self._run_ssh(['svctask', 'stopfcmap', map_id])
                    self._run_ssh(['svctask', 'rmfcmap', '-force', map_id])
                elif status == 'idle_or_copied':

                    self._run_ssh(['svctask', 'rmfcmap', '-force', map_id])
                else:
                    wait_for_copy = True
        if wait_for_copy:
            time.sleep(5)
        mapping_ids = self._get_vdisk_fc_mappings(name)
    return True

